// Fills each <section data-scene="id"> table from data/autograd_trace.json
// (generated by visualizations/examples/autograd_trace.cpp from the real library).
// All paths are relative, so the site works at / and under /TorC/.
const fmt = (t) => {
  if (!t) return '—';
  const f = (v) => { const s = Number(v.toPrecision(4)).toString(); return s === '-0' ? '0' : s; };
  return t.values.length === 1 ? f(t.values[0]) : '[' + t.values.map(f).join(', ') + ']';
};
const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text !== undefined) e.textContent = text; return e; };

fetch('data/autograd_trace.json').then(r => r.json()).then(data => {
  for (const sec of document.querySelectorAll('[data-scene]')) {
    const s = data.scenes.find(x => x.id === sec.dataset.scene);
    if (!s) continue;
    const wrap = el('div', 'tablewrap');
    const t = el('table');
    const head = el('tr'); ['node', 'op', 'inputs (from the tape)', 'value', 'grad'].forEach(h => head.append(el('th', '', h)));
    t.append(head);
    for (const n of s.nodes) {
      const r = el('tr');
      r.append(el('td', '', n.name), el('td', '', n.role === 'leaf' ? 'leaf' : n.op), el('td', '', n.inputs.join(', ') || '—'),
               el('td', 'v', fmt(n.value)), el('td', 'g', n.name === s.root ? '— (root: seed 1, never stored)' : fmt(n.grad)));
      t.append(r);
    }
    wrap.append(t);
    sec.querySelector('.values').replaceChildren(wrap);

    const fd = sec.querySelector('.fd');
    const worst = Math.max(...s.finite_difference.leaves.map(l => l.max_abs_err));
    const ok = s.finite_difference.leaves.every(l => l.ok);
    fd.replaceChildren(el('span', ok ? 'ok' : 'warn',
      (ok ? '✓ ' : '✗ ') + 'finite differences (h=' + Number(s.finite_difference.h.toPrecision(3)) + ') agree with autograd: max |Δ| = ' + worst.toExponential(1) + ' (tolerance ' + s.finite_difference.atol + ')'));
  }
}).catch(err => {
  for (const e of document.querySelectorAll('.values')) e.textContent = 'Could not load data/autograd_trace.json (serve the site over HTTP, not file://): ' + err;
});
